    /// One zeroed record, read through its view.
    private static func record<View: HandleView>(of view: View.Type) -> View {
        let base = UnsafeMutableRawPointer.allocate(byteCount: View.byteCount, alignment: 16)
        base.initializeMemory(as: UInt8.self, repeating: 0, count: View.byteCount)
        return View(handle: OpaquePointer(base))
    }

    /// One zeroed C array of `count` records, with the view's stride, so a slot address is the pointer Raven's `table + i` gave.
    private static func records<View: HandleView>(count: Int, of view: View.Type) -> Slots<View> {
        let base = UnsafeMutableRawPointer.allocate(byteCount: count * View.stride, alignment: 16)
        base.initializeMemory(as: UInt8.self, repeating: 0, count: count * View.stride)
        return Slots(views: base, count: count, stride: View.stride)
    }

    /// One table of `count` pointers, zeroed, read as optional views and written as handles.
    private static func table<View: HandleView>(count: Int, of view: View.Type) -> Slots<View?> {
        let stride = MemoryLayout<OpaquePointer?>.stride
        let base = UnsafeMutableRawPointer.allocate(byteCount: count * stride, alignment: MemoryLayout<OpaquePointer?>.alignment)
        base.initializeMemory(as: UInt8.self, repeating: 0, count: count * stride)
        return Slots(
            base: base,
            count: count,
            stride: stride,
            read: { $0.load(as: OpaquePointer?.self).map { View(handle: $0) } },
            write: { $0.storeBytes(of: $1?.handle, as: OpaquePointer?.self) }
        )
    }
